def chunks(start, end, days: int):
    """Split a range into calendar-aligned windows.

    A year of 15-minute data in one request is a good way to get a timeout from
    energy-charts and a 400 from ENTSO-E (which caps most endpoints at a year
    anyway). days=0 means one request for the lot.
    """
    if not days:
        yield start, end
        return
    while start < end:
        stop = min(start + pd.DateOffset(days=days), end)
        yield start, stop
        start = stop


def collect_range(backend: Backend, start, end, freq: str, physical: bool,
                  neighbours: list, chunk_days: int) -> pd.DataFrame:
    """collect() over a whole range, chunk by chunk. Bad chunks are dropped."""
    windows = list(chunks(start, end, chunk_days))
    frames = []
    for i, (cs, ce) in enumerate(windows, 1):
        if len(windows) > 1:
