/** Which x positions get a date label.
 *  Counted back from the last day, so the most recent date is always labelled
 *  and the spacing stays even -- labelling every nth from the left and then
 *  forcing the last one lands two labels on top of each other. How many fit is
 *  a function of the plot width, not a constant: eight labels that breathe on a
 *  desktop run into each other at 390px. */
function labelIndices(n, plotW) {
  const target = Math.max(3, Math.min(8, Math.floor(plotW / 72)));
  const every = Math.max(1, Math.ceil(n / target));
  const idx = new Set();
  for (let i = n - 1; i >= 0; i -= every) idx.add(i);
  return idx;
}

