function drawLevels(host, days, ref) {
  const sum = f => days.reduce((a, d) => a + (d[f] ?? 0), 0);
  const wmv = t => {
    const v = days.reduce((a, d) => a + (d[`${t}_gwh`] ?? 0), 0);
    const n = days.reduce((a, d) => a + (d[`${t}_gwh`] ?? 0) * (d[`${t}_mv`] ?? 0), 0);
    return v > 0 ? n / v : null;
  };
  const paid = sum("stayed_gwh") ? days.reduce((a, d) =>
        a + (d.stayed_gwh ?? 0) * (d.imp_px_own ?? 0), 0) / sum("stayed_gwh") : null;
